    Integer namesakeCount = owner.getNamesakeCount();
    String email = owner.getEmail();
    boolean unique = namesakeCount != null && namesakeCount == 0;
    boolean hasEmail = email != null && !email.isBlank();
    return (unique && hasEmail) ? "SILVER" : "BRONZE";
}

